; mixer.asm -- chapter 36: register 7's top two bits
; generated by gen36.py
        INCLUDE "msx.inc"
        OUTPUT "mixer.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
ticks   EQU VARS                ; frames counted by isr
count   EQU VARS + 1            ; the script's frames still to count
next    EQU VARS + 2            ; and where its next writes are
byte    EQU VARS + 4            ; show: the register just read
port1   EQU VARS + 5            ; mixer.asm: register 14 of port 1
r7      EQU VARS + 6            ; register 7, read back
r15     EQU VARS + 7            ; register 15, read back
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; WHERE IT BREAKS. A note on channel A, and joystick 1 read every frame; the
; script writes register 7 as if it had six bits, then with bits 6 and 7 set.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: chapter 30's set at 32
        ld hl, shapes
        ld e, 4
        call send
        VRAM_WRITE $2000        ; black ink on white paper
        ld a, $1F
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        ld hl, script           ; the first count
        ld a, (hl)
        inc hl
        ld (count), a
        ld (next), hl
        VDP_REG 1, $E0          ; the display on, and the frame's signal
        in a, (VDP_CTRL)
main:   ei
        halt                    ; wait for the frame
        di                      ; the interrupts off: the PSG, then the VDP
        call step               ; this frame's writes, if any
        xor a                   ; joystick 1
        call joy
        ld (port1), a
        ld a, 7                 ; registers 7 and 15, as they read back
        call reg
        ld (r7), a
        ld a, 15
        call reg
        ld (r15), a
read:   ld d, 4
        ld e, 6
        call at
        ld a, (port1)
        call cells
        ld e, 16
        call at
        ld a, (port1)
        call hex
        ld d, 6
        ld e, 6
        call at
        ld a, (r7)
        cpl
        call cells
        ld e, 16
        call at
        ld a, (r7)
        call hex
        ld d, 8
        ld e, 6
        call at
        ld a, (r15)
        cpl
        call cells
        ld e, 16
        call at
        ld a, (r15)
        call hex
        jp main

; step: the script's count down by one; when it runs out, its registers
; written, pair after pair, and the next count read. A count of 0 is the
; end. Uses A, E, HL
step:   ld hl, count            ; 11
        ld a, (hl)              ;  8
        or a                    ;  5
        ret z                   ; 12, or 6   the script is over
        dec (hl)                ; 12
        ret nz                  ; 12, or 6   not yet
        ld hl, (next)           ; 17
.pair:  ld a, (hl)              ;  8  a register, or $FF
        inc hl                  ;  7
        cp $FF                  ;  8
        jr z, .end              ; 13, or 8
        ld e, (hl)              ;  8  its byte
        inc hl                  ;  7
        call psg                ; 18
        jr .pair                ; 13
.end:   ld a, (hl)              ;  8  the next count
        inc hl                  ;  7
        ld (count), a           ; 14
        ld (next), hl           ; 17
        ret                     ; 11

; psg: A = a register, E = a byte -> the byte in that register. Uses A
psg:    out (PSG_ADDR), a       ; 12  the register
        ld a, e                 ;  5
        out (PSG_WRITE), a      ; 12  the byte
        ret                     ; 11

; joy: A = $00 for port 1, $40 for port 2 -> A = that port's register 14, a 0
; for each switch closed. Register 15's other seven bits are kept. The
; interrupts must be off. Uses A, B
joy:    ld b, a                 ;  5
        ld a, 15                ;  8
        out (PSG_ADDR), a       ; 12  register 15
        in a, (PSG_READ)        ; 12  as it is
        and $BF                 ;  8  bit 6: the port
        or b                    ;  5
        out (PSG_WRITE), a      ; 12
        ld a, 14                ;  8
        out (PSG_ADDR), a       ; 12  register 14
        in a, (PSG_READ)        ; 12  the port's pins
        ret                     ; 11

; reg: A = a register of the PSG -> A = its value. Uses A
reg:    out (PSG_ADDR), a
        in a, (PSG_READ)
        ret

; isr: every frame, a frame counted. Keeps AF
isr:    push af
        in a, (VDP_CTRL)        ; the status: the signal down
        ld a, (ticks)
        inc a
        ld (ticks), a
        pop af
        ei
        ret

; at: the next characters go to row D, column E (chapter 30)
at:     ld a, d
        rrca
        rrca
        rrca
        ld c, a
        and $E0
        or e
        out (VDP_CTRL), a
        ld a, c
        and $03
        or $18 | $40
        out (VDP_CTRL), a
        ret

; cells: A as eight boxes from bit 7, a filled box for a 0 (a key held) and
; an empty one for a 1, from the address set. Uses A, B, L
cells:  ld l, a
        ld b, 8
.cell:  ld a, 2
        rlc l                   ; the next bit, into the carry
        jr nc, .put             ; 0: held
        ld a, 1
.put:   out (VDP_DATA), a
        djnz .cell
        ret

; hex: A as two hexadecimal digits, from the address set. Uses A, C
hex:    ld c, a
        rrca
        rrca
        rrca
        rrca
        call .digit
        ld a, c
.digit: and $0F
        add a, '0'
        cp '9' + 1
        jr c, .out
        add a, 'A' - '9' - 1
.out:   out (VDP_DATA), a
        ret

; send: E blocks of 256 bytes from HL to the VDP
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret
